actions.script:
const ids = Array.from(accountList).map((account) => account.userId)
// no external user is found by anyone (a failed check leaves everyone out)
const outside = ids.length ? ec.service.sync().name('org.moqui.chat.ChatServices.get#ExternalUsers').parameter('userIdList', ids)
        .disableAuthz().call() : {externalUserIdList: []}
const external = new Set(outside ? Array.from(outside.externalUserIdList || []) : ids)
const inside = ids.filter((id) => !external.has(id))
const refused = new Set(inside.length ? ec.service.sync().name('org.moqui.chat.ChatServices.get#RefusedUsers')
        .parameters({userIdList: inside, hook: purpose === 'call' ? 'call-target' : 'chat-target'}).call()?.refusedUserIdList || [] : [])
userList = Array.from(accountList).filter((account) => !external.has(account.userId) && !refused.has(account.userId))
        .slice(0, pageLimit).map((account) => ({id: account.userId, value: account.userId,
    label: account.userFullName || account.username}))
